package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen0Test {

    @Test
    public void testPrintRecords_EmptyResultSet() throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(3);
        // resultSet.next() returns false immediately
        when(resultSet.next()).thenReturn(false);

        printer.printRecords(resultSet);
        printer.close();

        assertEquals("", sb.toString());
    }

    @Test
    public void testPrintRecords_WithData() throws Exception {
        StringBuilder sb = new StringBuilder();
        // Using RFC4180 to ensure standard CSV behavior (comma separation)
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.RFC4180);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);

        // Simulate two rows of data
        // Row 1: "val1", "val2"
        // Row 2: "val3", "val4"
        when(resultSet.next()).thenReturn(true, true, false);
        when(resultSet.getString(1)).thenReturn("val1", "val3");
        when(resultSet.getString(2)).thenReturn("val2", "val4");

        printer.printRecords(resultSet);
        printer.close();

        // CSVPrinter with RFC4180 adds CRLF and commas
        // Expected: val1,val2\r\nval3,val4\r\n
        String expected = "val1,val2" + System.lineSeparator() + "val3,val4" + System.lineSeparator();
        // Note: CSVPrinter uses \r\n by default for line separators in many versions, 
        // but since we use the Appendable, we check if the content matches the logical structure.
        // For strictness in unit testing against the provided logic:
        String result = sb.toString().replace("\r\n", System.lineSeparator());
        String expectedNormalized = "val1,val2" + System.lineSeparator() + "val3,val4" + System.lineSeparator();

        assertEquals(expectedNormalized, result);
    }

    @Test(expected = SQLException.class)
    public void testPrintRecords_SQLExceptionOnMetaData() throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);

        when(resultSet.getMetaData()).thenThrow(new SQLException("Meta error"));

        printer.printRecords(resultSet);
        printer.close();
    }

    @Test(expected = SQLException.class)
    public void testPrintRecords_SQLExceptionOnNext() throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenThrow(new SQLException("Next error"));

        printer.printRecords(resultSet);
        printer.close();
    }

    @Test(expected = SQLException.class)
    public void testPrintRecords_SQLExceptionOnGetString() throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenReturn(true);
        when(resultSet.getString(1)).thenThrow(new SQLException("Get error"));

        printer.printRecords(resultSet);
        printer.close();
    }

    @Test
    public void testPrintRecords_SingleColumn() throws Exception {
        StringBuilder sb = new StringBuilder();
        CSVPrinter printer = new CSVPrinter(sb, CSVFormat.DEFAULT);
        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenReturn(true, false);
        when(resultSet.getString(1)).thenReturn("onlyOne");

        printer.printRecords(resultSet);
        printer.close();

        String result = sb.toString().replace("\r\n", System.lineSeparator());
        assertEquals("onlyOne" + System.lineSeparator(), result);
    }
}
